void mrb_gc_mark_context_stack(mrb_state *mrb, struct mrb_context *c) {
  if (!c->stack) return;

  mrb_value *sp = c->stack + c->stack_size;
  mrb_value *base = c->stack;

  while (base < sp) {
    mrb_gc_mark(mrb, *base);
    base++;
  }

  while (base < c->stack + MRB_STACK_SIZE) {
    *base++ = mrb_nil_value();
  }
}

void mrb_mark_context_stack(mrb_state *mrb, struct mrb_context *c) {
  mrb_value *sp;
  mrb_int i;

  if (c->stack == NULL) {
    return;
  }

  sp = c->stack + c->stack_size;

  for (i = 0; i < (sp - c->stack); i++) {
    mrb_value *v = &c->stack[i];
    if (!mrb_immediate_p(*v)) {
      mrb_gc_mark(mrb, *v);
    }
  }

  for (; i < c->stack_size; i++) {
    c->stack[i] = mrb_nil_value();
  }
}

void mrb_gc_mark_context(mrb_state *mrb, struct mrb_context *c) {
  mrb_value *sp;
  int i;

  if (!c->stack) return;
  sp = c->stack + c->stack_size;
  for (i = c->ci->nlocals; i > 0; i--) {
    mrb_gc_mark(mrb, *--sp);
  }
  while (sp > c->stack) {
    *--sp = mrb_nil_value();
  }
}

void mrb_gc_mark_context_stack(mrb_state *mrb, struct mrb_context *c) {
  mrb_value *sp;
  size_t i;

  if (c->stack == NULL) {
    return;
  }

  sp = c->sp - c->stack;
  for (i = 0; i < sp; i++) {
    mrb_value v = c->stack[i];
    if (!mrb_immediate_p(v)) {
      mrb_gc_mark(mrb, v);
    }
  }

  for (; i < MRB_STACK_LIMIT; i++) {
    c->stack[i] = mrb_nil_value();
  }
}

void mrb_gc_mark_context(mrb_state *mrb, struct mrb_context *c) {
  mrb_value *sp = c->ci->stack;
  mrb_value *ep = c->stack + c->stack_size;
  mrb_value *ptr;

  if (c->stack == NULL) return;

  for (ptr = c->stack; ptr < sp; ptr++) {
    if (!mrb_immediate_p(*ptr)) {
      mrb_gc_mark(mrb, *ptr);
    }
  }

  for (; ptr < ep; ptr++) {
    *ptr = mrb_nil_value();
  }
}
